const body = $input.first().json.body || {};
const targetRole = body.target_role || 'Full-Stack AI Engineer';
const skills = body.skills || ['React', 'n8n', 'Pinecone'];
const minBudget = body.min_fixed_budget || 500;

// Real-world Upwork RFP job templates tailored to incoming user intake
const jobs = [
  {
    title: `Senior ${targetRole} Needed for AI Workflow Automation`,
    link: "https://www.upwork.com/jobs/~01a2b3c4d5e6f7a8b9",
    description: `We are looking for an expert ${targetRole} to build an end-to-end automated RFP intelligence pipeline using ${skills.join(', ')}. Must have experience with vector databases and LLM orchestration.`,
    budget_type: "Fixed",
    budget_value: Math.max(minBudget, 1200),
    pubDate: new Date().toUTCString(),
    guid: "job_upwork_rfp_01"
  },
  {
    title: "Build Production RAG & Vector Search Integration",
    link: "https://www.upwork.com/jobs/~02b3c4d5e6f7a8b9c0",
    description: `Seeking a skilled developer to build a RAG application with Pinecone and FastAPI. Required tech stack: ${skills.slice(0, 3).join(', ')}. Clean architecture and high accuracy required.`,
    budget_type: "Hourly",
    budget_value: 65,
    pubDate: new Date(Date.now() - 3600000).toUTCString(),
    guid: "job_upwork_rfp_02"
  },
  {
    title: "n8n Custom Nodes & Webhook Integration Engineer",
    link: "https://www.upwork.com/jobs/~03c4d5e6f7a8b9c0d1",
    description: `Need an n8n workflow expert to automate lead intake, AI summary generation, and database sync. Skills needed: n8n, Webhooks, REST APIs, ${skills[0] || 'React'}.`,
    budget_type: "Fixed",
    budget_value: Math.max(minBudget, 850),
    pubDate: new Date(Date.now() - 7200000).toUTCString(),
    guid: "job_upwork_rfp_03"
  }
];

return jobs.map(job => ({ json: job }));
